import math
import numpy as np
import pandas as pd

def make_bars(n=1260, seed=2301, mu=0.0003, sigma=0.012, phi=0.06):
    rng = np.random.default_rng(seed)
    eps = sigma * rng.standard_normal(n)
    r = np.empty(n)
    prev = 0.0
    for t in range(n):
        r[t] = mu + phi * prev + eps[t]        # AR(1) log returns: weak momentum
        prev = r[t] - mu
    close = 100 * np.exp(np.cumsum(r))
    prev_close = np.r_[100.0, close[:-1]]
    gap = 0.5 * r + 0.002 * rng.standard_normal(n)   # half of each day's move is overnight
    open_ = prev_close * np.exp(gap)
    w = sigma * 0.5 * np.abs(rng.standard_normal((2, n)))
    high = np.maximum(open_, close) * np.exp(w[0])
    low = np.minimum(open_, close) * np.exp(-w[1])
    volume = np.round(rng.lognormal(np.log(2e6), 0.3, n))
    idx = pd.bdate_range("2019-01-02", periods=n)
    return pd.DataFrame({"open": open_, "high": high, "low": low,
                         "close": close, "volume": volume}, index=idx)

# ---- levels 1 to 3, already defined ----
def momentum_signal(close, lookback):
    return np.sign(close.pct_change(lookback)).fillna(0.0)

def target_positions(signal, max_units):
    s = pd.Series(signal, dtype=float).fillna(0.0).clip(-1, 1)
    return np.round(s * max_units)

class Portfolio:
    def __init__(self, cash):
        self.cash = float(cash)
        self.shares = 0
    def fill(self, qty, price, cost=0.0):
        self.cash -= qty * price + cost
        self.shares += qty
    def equity(self, price):
        return self.cash + self.shares * price

def backtest(bars, targets, cash0=1_000_000, costs=None):
    tg = np.asarray(targets, dtype=float)
    orders = np.diff(np.r_[0.0, tg])
    op, cl = bars["open"].to_numpy(), bars["close"].to_numpy()
    pf, rows = Portfolio(cash0), []
    for t in range(len(cl)):
        if t > 0 and orders[t - 1] != 0:
            q, px = orders[t - 1], op[t]
            pf.fill(q, px, costs(q, px) if costs else 0.0)
        rows.append((pf.shares, pf.cash, pf.equity(cl[t])))
    return pd.DataFrame(rows, index=bars.index, columns=["shares", "cash", "equity"])

def bp_costs(cost_bp):
    return lambda qty, price: abs(qty) * price * cost_bp / 10_000

def run_rule(bars, lookback, cost_bp, max_units=10_000, cash0=1_000_000):
    targets = target_positions(momentum_signal(bars["close"], lookback), max_units)
    return backtest(bars, targets, cash0, bp_costs(cost_bp))

def sharpe(returns, periods=252):
    x = pd.Series(returns, dtype=float).dropna()
    if len(x) < 2:
        return 0.0
    sd = x.std(ddof=1)
    if not sd > 1e-15:
        return 0.0
    return float(math.sqrt(periods) * x.mean() / sd)

def net_sharpe(bars, lookback, cost_bp):
    return sharpe(run_rule(bars, lookback, cost_bp)["equity"].pct_change())

def drawdown(equity):
    e = pd.Series(equity, dtype=float)
    return e / e.cummax() - 1

def max_drawdown(equity):
    return float(min(drawdown(equity).min(), 0.0))

def cagr(equity, periods=252):
    e = pd.Series(equity, dtype=float)
    return float((e.iloc[-1] / e.iloc[0]) ** (periods / (len(e) - 1)) - 1)

def calmar(equity, periods=252):
    mdd = max_drawdown(equity)
    return math.inf if mdd == 0 else cagr(equity, periods) / abs(mdd)

def turnover(positions):
    p = pd.Series(positions, dtype=float)
    return float(p.diff().fillna(p.iloc[0]).abs().mean())

def trade_cost(qty, price, per_share=0.005, minimum=1.0, half_spread_bp=2.0):
    if qty == 0:
        return 0.0
    q = abs(qty)
    return max(per_share * q, minimum) + q * price * half_spread_bp / 10_000

def buy_and_hold(bars, cash0=1_000_000):
    o0 = bars["open"].iloc[0]
    shares = int(cash0 // o0)                       # whole shares at the first open
    cash = cash0 - shares * o0 - trade_cost(shares, o0)
    return cash + shares * bars["close"]

def metrics(equity, positions, bench_equity):
    e = pd.Series(equity, dtype=float)
    r = e.pct_change().iloc[1:]
    b = pd.Series(bench_equity, dtype=float).pct_change().iloc[1:]
    pos = pd.Series(positions, dtype=float)
    active = (pos.iloc[1:] != 0).to_numpy()
    hit = float((r.to_numpy()[active] > 0).mean()) if active.any() else float("nan")
    bv = b.var(ddof=1)
    beta = float(np.cov(r.to_numpy(), b.to_numpy(), ddof=1)[0, 1] / bv) if bv > 0 else float("nan")
    m = {"ann_return": cagr(e), "ann_vol": float(r.std(ddof=1) * math.sqrt(252)),
         "sharpe": sharpe(r), "max_drawdown": max_drawdown(e), "calmar": calmar(e),
         "turnover": turnover(pos), "hit_rate": hit, "beta": beta}
    return {k: round(v, 4) for k, v in m.items()}

def weights(result, bars):
    return result["shares"] * bars["close"] / result["equity"]

def split_holdout(bars, n_holdout=252, gap=0):
    n = len(bars)
    return bars.iloc[: n - n_holdout - gap], bars.iloc[n - n_holdout:]

