import numpy as np

def expected_max_sharpe(n, sd, sims=2000, seed=0):
    if n == 1:
        return 0.0
    rng = np.random.default_rng(seed)
    draws = rng.standard_normal((sims, n))     # sims searches of n no-edge settings
    return round(float(draws.max(axis=1).mean() * sd), 3)

def deflated_verdict(best, n, sd):
    return bool(best > expected_max_sharpe(n, sd))
